// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deposit 1 ether into the contract via fallback
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");

        // Call withdrawAll with the test contract as recipient
        vm.prank(address(this));
        c.withdrawAll(address(this));

        // Assert: the contract's balance should be 0 (reference) vs 1 ether (bug)
        assertTrue(address(c).balance == 0, "Contract balance should be zero after withdrawAll");
    }
}
